{
  const btnStyle = 'padding:6px 12px;border:1px solid var(--border);border-radius:6px;background:none;color:var(--text-primary);font-size:12px;cursor:pointer;';
  const primaryBtnStyle = 'padding:6px 14px;border:1px solid var(--success,#3ecf5d);border-radius:6px;background:var(--success,#3ecf5d);color:#06210f;font-size:12px;font-weight:600;cursor:pointer;';
  const sectionStyle = 'margin:0 0 16px;padding-bottom:16px;border-bottom:1px solid var(--border);';
  const labelStyle = 'font-size:11px;font-weight:700;letter-spacing:.05em;color:var(--text-muted);margin-bottom:8px;';
  const serialOk = helpers.serial && helpers.serial.isSupported();

  const statusEl = document.createElement('p');
  statusEl.style.cssText = 'margin:0 0 12px;font-size:12px;color:var(--text-muted);';
  container.appendChild(statusEl);

  const connectRow = document.createElement('div');
  connectRow.style.cssText = 'display:flex;gap:8px;margin-bottom:16px;';
  const connectBtn = document.createElement('button');
  connectBtn.type = 'button';
  connectBtn.textContent = 'Connect (COM)';
  connectBtn.style.cssText = btnStyle;
  connectBtn.disabled = !serialOk;
  connectBtn.title = serialOk ? '' : 'Web Serial is not available in this browser (Chrome or Edge on desktop)';
  const wifiBtn = document.createElement('button');
  wifiBtn.type = 'button';
  wifiBtn.textContent = 'Connect (WiFi)';
  wifiBtn.style.cssText = btnStyle;
  const disconnectBtn = document.createElement('button');
  disconnectBtn.type = 'button';
  disconnectBtn.textContent = 'Disconnect';
  disconnectBtn.style.cssText = btnStyle;
  disconnectBtn.disabled = true;
  connectRow.append(connectBtn, wifiBtn, disconnectBtn);
  container.appendChild(connectRow);

  // ── The machine: the CNC module's own web page, which already has the
  // status, jog, start/stop and file controls — shown inside the dialog
  // once the board says where it can be reached. This browser has to be
  // on the same network as that address (the board's own access point, or
  // the network it joined).
  const machineSection = document.createElement('div');
  machineSection.style.cssText = sectionStyle + 'display:none;';
  const machineHeader = document.createElement('div');
  machineHeader.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px;';
  const machineLabel = document.createElement('div');
  machineLabel.textContent = 'MACHINE';
  machineLabel.style.cssText = labelStyle + 'margin-bottom:0;';
  const machineState = document.createElement('span');
  machineState.style.cssText = 'font-family:ui-monospace,Consolas,monospace;font-size:11px;color:var(--text-secondary);flex:1;';
  machineState.textContent = 'state ?';
  const machineOpen = document.createElement('a');
  machineOpen.textContent = 'Open in a tab';
  machineOpen.target = '_blank';
  machineOpen.rel = 'noopener';
  machineOpen.style.cssText = 'font-size:11px;color:var(--text-muted);';
  const machineReload = document.createElement('button');
  machineReload.type = 'button';
  machineReload.textContent = 'Reload';
  machineReload.style.cssText = btnStyle + 'padding:3px 10px;font-size:11px;';
  machineHeader.append(machineLabel, machineState, machineOpen, machineReload);
  machineSection.appendChild(machineHeader);
  const machineFrame = document.createElement('iframe');
  machineFrame.style.cssText = 'width:100%;height:520px;border:1px solid var(--border);border-radius:6px;background:#0d1117;';
  machineFrame.setAttribute('title', 'CNC module page');
  machineSection.appendChild(machineFrame);
  const machineHint = document.createElement('div');
  machineHint.style.cssText = 'font-size:11px;color:var(--text-muted);margin-top:6px;';
  machineSection.appendChild(machineHint);
  container.appendChild(machineSection);
  // The page needs room: widen this dialog's panel while it is open.
  const panel = container.closest('.noditron-dialog-panel');
  if (panel) panel.style.maxWidth = 'min(960px, calc(100vw - 32px))';
  let machineUrl = '';
  function showMachinePage(ip) {
    if (!ip || ip === '-' || ip === '0.0.0.0') {
      machineFrame.style.display = 'none';
      machineOpen.style.display = 'none';
      machineHint.textContent = 'The board has no network address yet -- turn on its access point or join a network below, then Reload.';
      return;
    }
    machineUrl = 'http://' + ip + '/';
    machineFrame.style.display = '';
    machineOpen.style.display = '';
    machineOpen.href = machineUrl;
    machineFrame.src = machineUrl;
    machineHint.textContent = 'The module\'s own page at ' + machineUrl + ' -- reachable when this computer is on that network (its access point, or the network it joined). Gcode also goes through the shell below as g <line>, and from the block\'s gcode input.';
  }
  machineReload.addEventListener('click', async () => {
    try {
      const info = await helpers.console.identify();
      showMachinePage(info.ip);
    } catch (err) {
      machineHint.textContent = err.message;
    }
  });
  // grbl reports its state on its own lines ([MSG:State: Idle], <Idle|...>),
  // usually after the shell's ok; read them as they arrive.
  if (helpers.console.subscribeLines) {
    const stopState = helpers.console.subscribeLines(({ line }) => {
      if (!container.isConnected) { stopState(); return; }
      const msg = line.match(/^\[MSG:State: (\w+)\]/);
      const report = line.match(/^<(\w+)[|>]/);
      if (msg) machineState.textContent = 'state ' + msg[1];
      else if (report) machineState.textContent = 'state ' + report[1];
    });
  }

  // ── Connectivity: who is around, and the board's radios — read and
  // driven through the board's own shell (nodes / wifi status / wifi list /
  // wifi select + pw / wifi on|off / ap on|off), the same commands a
  // terminal on the USB port, or a CAN hop, would type. ──
  const netSection = document.createElement('div');
  netSection.style.cssText = sectionStyle + 'display:none;';
  const netLabel = document.createElement('div');
  netLabel.textContent = 'CONNECTIVITY';
  netLabel.style.cssText = labelStyle;
  netSection.appendChild(netLabel);
  const nodesEl = document.createElement('div');
  nodesEl.style.cssText = 'font-family:ui-monospace,Consolas,monospace;font-size:11px;color:var(--text-secondary);white-space:pre-wrap;margin-bottom:10px;';
  nodesEl.textContent = 'Nodes: ...';
  netSection.appendChild(nodesEl);
  function radioRow(labelText) {
    const row = document.createElement('label');
    row.style.cssText = 'display:flex;align-items:center;gap:8px;font-size:12px;margin-bottom:6px;cursor:pointer;';
    const box = document.createElement('input');
    box.type = 'checkbox';
    const name = document.createElement('span');
    name.textContent = labelText;
    name.style.cssText = 'font-weight:600;min-width:90px;';
    const status = document.createElement('span');
    status.style.cssText = 'color:var(--text-muted);flex:1;';
    row.append(box, name, status);
    netSection.appendChild(row);
    return { box, status };
  }
  const apRow = radioRow('Access point');
  const staRow = radioRow('WiFi');
  const staControls = document.createElement('div');
  staControls.style.cssText = 'display:none;flex-direction:column;gap:6px;margin:4px 0 8px 24px;';
  const scanRow = document.createElement('div');
  scanRow.style.cssText = 'display:flex;gap:6px;';
  const netSelect = document.createElement('select');
  netSelect.style.cssText = 'flex:1;min-width:0;padding:5px 6px;background:none;border:1px solid var(--border);border-radius:6px;color:var(--text-primary);font-size:12px;';
  const scanBtn = document.createElement('button');
  scanBtn.type = 'button';
  scanBtn.textContent = 'Scan';
  scanBtn.style.cssText = btnStyle;
  scanRow.append(netSelect, scanBtn);
  const pwRow = document.createElement('div');
  pwRow.style.cssText = 'display:flex;gap:6px;';
  const pwInput = document.createElement('input');
  pwInput.type = 'password';
  pwInput.placeholder = 'Password';
  pwInput.style.cssText = 'flex:1;min-width:0;padding:5px 6px;background:none;border:1px solid var(--border);border-radius:6px;color:var(--text-primary);font-size:12px;';
  const joinBtn = document.createElement('button');
  joinBtn.type = 'button';
  joinBtn.textContent = 'Connect';
  joinBtn.style.cssText = primaryBtnStyle;
  const forgetBtn = document.createElement('button');
  forgetBtn.type = 'button';
  forgetBtn.textContent = 'Forget';
  forgetBtn.style.cssText = btnStyle;
  pwRow.append(pwInput, joinBtn, forgetBtn);
  staControls.append(scanRow, pwRow);
  netSection.appendChild(staControls);
  const netHint = document.createElement('div');
  netHint.style.cssText = 'font-size:11px;color:var(--text-muted);';
  netSection.appendChild(netHint);
  container.appendChild(netSection);

  // ── Shell: the board's command line itself. Type help. ──
  const shellSection = document.createElement('div');
  shellSection.style.cssText = sectionStyle.replace('border-bottom:1px solid var(--border);', '');
  const shellLabel = document.createElement('div');
  shellLabel.textContent = 'SHELL';
  shellLabel.style.cssText = labelStyle + 'margin-bottom:0;';
  const shellHeader = document.createElement('div');
  shellHeader.style.cssText = 'display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;';
  const copyBtn = document.createElement('button');
  copyBtn.type = 'button';
  copyBtn.textContent = 'Copy';
  copyBtn.title = 'Copy the whole shell output to the clipboard';
  copyBtn.style.cssText = btnStyle + 'padding:3px 10px;font-size:11px;';
  shellHeader.append(shellLabel, copyBtn);
  const shellOut = document.createElement('pre');
  shellOut.style.cssText = 'margin:0 0 6px;padding:8px;border:1px solid var(--border);border-radius:6px;background:var(--bg-well);color:var(--text-secondary);font-family:ui-monospace,Consolas,monospace;font-size:11px;white-space:pre-wrap;word-break:break-word;max-height:160px;overflow:auto;';
  shellOut.textContent = String(props.connectionState || 'disconnected') + '\ntype help';
  const shellInput = document.createElement('input');
  shellInput.type = 'text';
  shellInput.placeholder = '> command';
  shellInput.style.cssText = 'width:100%;box-sizing:border-box;padding:6px 8px;background:none;border:1px solid var(--border);border-radius:6px;color:var(--text-primary);font-family:ui-monospace,Consolas,monospace;font-size:12px;';
  shellSection.append(shellHeader, shellOut, shellInput);
  const shellHistory = shellOut.textContent.split('\n');
  copyBtn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(shellHistory.join('\n'));
      copyBtn.textContent = 'Copied';
    } catch (err) {
      copyBtn.textContent = 'Copy failed';
    }
    setTimeout(() => { copyBtn.textContent = 'Copy'; }, 1500);
  });
  function shellPrint(text) {
    shellHistory.push(...String(text).split('\n'));
    while (shellHistory.length > 200) shellHistory.shift();
    shellOut.textContent = shellHistory.join('\n');
    shellOut.scrollTop = shellOut.scrollHeight;
  }
  // What the board says on its own shows up here too: a CAN reply that
  // lands after `can <text>` was already answered with ok, a circuit's
  // [USB] line, a node heard. Pin chatter and the pin-state JSON stay
  // out; a command's own reply is printed by the command below.
  if (helpers.console.subscribeLines) {
    const stopLines = helpers.console.subscribeLines(({ line, unsolicited }) => {
      if (!container.isConnected) { stopLines(); return; }
      if (!unsolicited || line === 'ok' || line.startsWith('{') || line.startsWith('[TCA9554]')) return;
      shellPrint(line);
    });
  }
  async function runShell(line) {
    if (!helpers.console.shell) return { ok: false, lines: [], error: 'no shell in this noditron' };
    return helpers.console.shell(line);
  }
  shellInput.addEventListener('keydown', async (event) => {
    if (event.key !== 'Enter') return;
    const line = shellInput.value.trim();
    if (!line) return;
    shellInput.value = '';
    shellPrint('> ' + line);
    try {
      const r = await runShell(line);
      if (r.lines.length) shellPrint(r.lines.join('\n'));
      if (!r.ok) shellPrint('error: ' + r.error);
    } catch (err) {
      shellPrint('error: ' + err.message);
    }
  });

  let netTimer = null;
  let netBusy = false;
  // The WiFi switch was turned on but the board has no network saved yet:
  // keep it on and show the controls until a network is joined.
  let staSetup = false;
  async function refreshConnectivity() {
    if (netBusy || !container.isConnected) return;
    netBusy = true;
    try {
      // Polls are short: a board without the shell's ok terminator (build
      // 20260924g) answers at once and then leaves the reader waiting.
      const asJson = (lines, pick) => lines.map((l) => { try { return JSON.parse(l); } catch (_) { return null; } }).find(pick);
      const nodes = await runShell('nodes', { timeoutMs: 1500 });
      let nodeLines = nodes.lines.filter((l) => /^(logic|cnc|node) [0-9a-f]{8}/.test(l));
      const nodesJson = asJson(nodes.lines, (j) => j && Array.isArray(j.nodes));
      if (!nodeLines.length && nodesJson) {
        nodeLines = nodesJson.nodes.map((n) => n.type + ' ' + n.id + ' v' + n.version
          + (n.self ? ' self' : ' seen ' + Math.round((n.ageMs || 0) / 1000) + 's ago via ' + (n.via || 'can')));
      }
      nodesEl.textContent = nodeLines.length ? 'Nodes:\n' + nodeLines.join('\n') : 'Nodes: ' + (nodes.lines.length ? 'unreadable reply' : nodes.error || 'no reply');
      const status = await runShell('wifi status', { timeoutMs: 1500 });
      let sta = status.lines.find((l) => /^sta (on|off)/.test(l)) || '';
      let ap = status.lines.find((l) => /^ap (on|off)/.test(l)) || '';
      const statusJson = asJson(status.lines, (j) => j && j.ap && j.sta);
      if (!sta && !ap && statusJson) {
        // Build 20260924g: JSON, and no on/off switches yet -- both radios are on.
        ap = 'ap on: ' + statusJson.ap.ssid + ' ' + statusJson.ap.ip + ' clients=' + statusJson.ap.clients;
        sta = statusJson.sta.connected
          ? 'sta on: connected ' + statusJson.sta.ssid + ' ip=' + statusJson.sta.ip + ' rssi=' + statusJson.sta.rssi
          : statusJson.sta.saved ? 'sta on: disconnected, saved ' + statusJson.sta.ssid : 'sta on: disconnected, no network saved';
      }
      if (sta.startsWith('sta on')) staSetup = false;
      staRow.box.checked = staSetup || sta.startsWith('sta on');
      staRow.status.textContent = sta.replace(/^sta (on|off):?\s*/, '') || (sta ? (staRow.box.checked ? 'on' : 'off') : '');
      apRow.box.checked = ap.startsWith('ap on');
      apRow.status.textContent = ap.replace(/^ap (on|off):?\s*/, '') || (ap ? (apRow.box.checked ? 'on' : 'off') : '');
      staControls.style.display = staRow.box.checked ? 'flex' : 'none';
      const all = nodes.lines.concat(status.lines);
      // An old build answers a shell word with grbl's numeric error or with JSON; a
      // board that is busy (restarting its radio, say) answers nothing for a while.
      if (!nodes.ok && !status.ok) {
        if (all.some((l) => /^error:\d+$/.test(l) || l.startsWith('{'))) netHint.textContent = 'This firmware has no shell yet -- switches and scan need the update above.';
        else netHint.textContent = 'No answer right now -- the board may be restarting its radio; trying again.';
      } else if (/^No answer right now/.test(netHint.textContent)) {
        netHint.textContent = '';
      }
    } catch (err) {
      netHint.textContent = err.message;
    } finally {
      netBusy = false;
    }
  }
  function startConnectivity() {
    netSection.style.display = '';
    refreshConnectivity();
    if (netTimer) return;
    netTimer = setInterval(() => {
      if (!container.isConnected || netSection.style.display === 'none') {
        clearInterval(netTimer);
        netTimer = null;
        return;
      }
      refreshConnectivity();
    }, 4000);
  }
  apRow.box.addEventListener('change', async () => {
    const r = await runShell(apRow.box.checked ? 'ap on' : 'ap off');
    if (!r.ok) netHint.textContent = r.error;
    refreshConnectivity();
  });
  staRow.box.addEventListener('change', async () => {
    if (!staRow.box.checked) {
      staSetup = false;
      const r = await runShell('wifi off');
      if (!r.ok) netHint.textContent = r.error;
      refreshConnectivity();
      return;
    }
    const r = await runShell('wifi on');
    if (!r.ok && /no network saved/i.test(r.error || '')) {
      staSetup = true;
      staControls.style.display = 'flex';
      netHint.textContent = 'No network saved yet: scan, pick one and enter its password.';
      return;
    }
    if (!r.ok) netHint.textContent = r.error;
    refreshConnectivity();
  });
  scanBtn.addEventListener('click', async () => {
    scanBtn.disabled = true;
    netHint.textContent = 'Scanning...';
    try {
      let r = await runShell('wifi list');
      for (let i = 0; i < 15 && r.lines.some((l) => l.startsWith('scanning')); i += 1) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
        r = await runShell('wifi list');
      }
      const nets = r.lines.map((l) => l.match(/^(\d+) (.+?) (-?\d+)dBm (secured|open)/)).filter(Boolean);
      netSelect.replaceChildren();
      for (const m of nets) {
        const option = document.createElement('option');
        option.value = m[2];
        option.textContent = m[2] + ' (' + m[3] + ' dBm, ' + m[4] + ')';
        netSelect.appendChild(option);
      }
      netHint.textContent = nets.length ? nets.length + ' network(s) in range.' : (r.error || 'No networks found.');
    } catch (err) {
      netHint.textContent = err.message;
    } finally {
      scanBtn.disabled = false;
    }
  });
  joinBtn.addEventListener('click', async () => {
    const ssid = netSelect.value;
    if (!ssid) { netHint.textContent = 'Scan and pick a network first.'; return; }
    joinBtn.disabled = true;
    try {
      const sel = await runShell('wifi select ' + ssid);
      if (!sel.ok) { netHint.textContent = sel.error; return; }
      const pw = await runShell('wifi pw ' + pwInput.value);
      netHint.textContent = pw.ok ? 'Joining ' + ssid + '...' : pw.error;
      if (pw.ok) staSetup = false;
      pwInput.value = '';
      setTimeout(refreshConnectivity, 3000);
    } finally {
      joinBtn.disabled = false;
    }
  });
  forgetBtn.addEventListener('click', async () => {
    await runShell('wifi forget');
    refreshConnectivity();
  });


  container.appendChild(shellSection);
  function log(line) {
    shellPrint(line);
  }

  function showRunning(info) {
    statusEl.textContent = 'grbl v' + info.version + ' build ' + info.build + ' running.';
    machineState.textContent = 'state ' + (info.machineState || '?');
    machineSection.style.display = '';
    showMachinePage(info.ip);
    startConnectivity();
  }

  async function afterPortOpen() {
    statusEl.textContent = 'Connected -- asking who is there...';
    try {
      const info = await helpers.console.identify();
      if (info.verified && info.kind === 'cnc') {
        log('ping: grbl v' + info.version + ' build ' + info.build + ', state ' + (info.machineState || '?') + '.');
        helpers.setProp('connectionState', 'connected:running');
        showRunning(info);
        return;
      }
      if (info.verified) {
        statusEl.textContent = 'That is a Logic Module, not a CNC module.';
        log('ping answered as a Logic Module (build ' + info.build + ').');
        helpers.setProp('connectionState', 'connected:unknown');
        return;
      }
      statusEl.textContent = 'Connected, but nothing answered as a CNC module. Its firmware may predate the module shell (build 20260925a).';
      helpers.setProp('connectionState', 'connected:unknown');
    } catch (err) {
      statusEl.textContent = 'Connected, but could not identify the board: ' + err.message;
      helpers.setProp('connectionState', 'connected:unknown');
    }
  }

  const existing = helpers.serial.getSession();
  if (existing) {
    disconnectBtn.disabled = false;
    connectBtn.disabled = true;
    wifiBtn.disabled = true;
    afterPortOpen();
  } else {
    statusEl.textContent = 'Not connected.';
  }

  connectBtn.addEventListener('click', async () => {
    connectBtn.disabled = true;
    wifiBtn.disabled = true;
    try {
      await helpers.serial.connect(log);
      log('Serial port opened.');
      disconnectBtn.disabled = false;
      await afterPortOpen();
    } catch (err) {
      statusEl.textContent = 'Connect failed: ' + err.message;
      connectBtn.disabled = !serialOk;
      wifiBtn.disabled = false;
    }
  });

  wifiBtn.addEventListener('click', async () => {
    if (!helpers.serial.connectWifi) { log('This noditron has no WiFi link yet.'); return; }
    const last = (helpers.serial.rememberedWifi && helpers.serial.rememberedWifi()) || '192.168.0.1';
    const host = window.prompt('Board address: its IP or name on your network, or 192.168.0.1 on its own access point.', last);
    if (!host) return;
    wifiBtn.disabled = true;
    connectBtn.disabled = true;
    try {
      await helpers.serial.connectWifi(host, log);
      disconnectBtn.disabled = false;
      await afterPortOpen();
    } catch (err) {
      statusEl.textContent = 'WiFi connect failed: ' + err.message;
      log('WiFi connect failed: ' + err.message);
      wifiBtn.disabled = false;
      connectBtn.disabled = !serialOk;
    }
  });

  disconnectBtn.addEventListener('click', async () => {
    helpers.console.close();
    await helpers.serial.disconnect(true);
    statusEl.textContent = 'Disconnected.';
    connectBtn.disabled = !serialOk;
    wifiBtn.disabled = false;
    disconnectBtn.disabled = true;
    machineSection.style.display = 'none';
    netSection.style.display = 'none';
    helpers.setProp('connectionState', 'disconnected');
  });
}

